import os
import random
import numpy as np
import torch


class Config:
    # --------------------------------------------------------------------------
    # Directory & File Paths
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata CSVs (Generated by the provided script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "validation.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output Directories
    WORKING_DIR = "./working"
    IDEA_DIR = os.path.join(WORKING_DIR, "idea_1")
    CHECKPOINT_DIR = os.path.join(IDEA_DIR, "checkpoints")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Ensure output directories exist
    os.makedirs(CHECKPOINT_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # --------------------------------------------------------------------------
    # Data Parameters
    # --------------------------------------------------------------------------
    IMAGE_SIZE = 256
    NUM_BANDS = 3  # Ash composite has 3 channels

    # Ash Composite Normalization Bounds (Min, Max)
    # Red: Band 15 - Band 14 (Optical Depth)
    ASH_RED_BOUNDS = (-6.7, 2.6)
    # Green: Band 14 - Band 11 (Particle Phase)
    ASH_GREEN_BOUNDS = (-6.3, 5.0)  # Adjusted based on common Ash recipes
    # Blue: Band 14 (Temperature in Kelvin)
    ASH_BLUE_BOUNDS = (243.0, 303.0)

    # --------------------------------------------------------------------------
    # Model Hyperparameters
    # --------------------------------------------------------------------------
    SEED = 42
    BATCH_SIZE = 64  # Increased for gradient stability Cite solution_lesson_node_00006
    EPOCHS = 25  # Extended convergence Cite solution_lesson_node_00006
    LEARNING_RATE = 1e-4  # Reduced for stability Cite solution_lesson_node_00006
    WEIGHT_DECAY = 1e-5

    # Loss Weights
    BCE_WEIGHT = 0.5
    DICE_WEIGHT = 0.5

    # Threshold for converting probability to binary mask
    THRESHOLD = 0.5

    # --------------------------------------------------------------------------
    # System Configuration
    # --------------------------------------------------------------------------
    NUM_WORKERS = 4  # 12 vCPUs available
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @staticmethod
    def set_seed(seed=42):
        """
        Sets the random seed for reproducibility across Python, NumPy, and PyTorch.
        """
        random.seed(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed(seed)
        # Ensure deterministic behavior in CuDNN
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False
        os.environ["PYTHONHASHSEED"] = str(seed)
